def asset_uri(filename):
    file=ROOT/'assets'/filename
    return 'data:image/png;base64,'+base64.b64encode(file.read_bytes()).decode('ascii')

def picture(filename, alt, width='100%', maxheight='none'):
    return f'<img src="{asset_uri(filename)}" alt="{html.escape(alt)}" style="width:{width};max-height:{maxheight};object-fit:contain;border-radius:10px"/>'

