def squad_xi(squad):
    pool=squad.sort_values('Minutos jugados',ascending=False).copy()
    used=set()
    def take(pos):
        for _,r in pool.iterrows():
            if r['Position'] in pos and r['Player'] not in used:
                used.add(r['Player']);return r
        return None
    gk=take(['GK']); defenders=[take(['DEF']) for _ in range(4)]
    pivots=[take(['MID']) for _ in range(2)]
    striker=take(['FWD'])
    attack=[take(['FWD','MID']) for _ in range(3)]
    return [([gk],['GK']), (defenders,['LB','CB','CB','RB']), (pivots,['DM','DM']), (attack,['LW','AM','RW']), ([striker],['ST'])]

def pitch_html(rows):
    bands=[]
    for players,roles in reversed(rows):
        cards=[]
        for p,role in zip(players,roles):
            if p is None:continue
            cards.append('<div class="xi-player"><div class="xi-role">'+role+'</div><div class="xi-name">'+html.escape(str(p['Player']))+'</div><div class="xi-min">'+str(int(p['Minutos jugados']))+' min</div></div>')
        bands.append('<div class="xi-line">'+''.join(cards)+'</div>')
    return '<div class="xi-pitch">'+''.join(bands)+'</div>'

