def metric_value(row, metric, normalize=True):
    value = pd.to_numeric(row[metric], errors='coerce')
    if not normalize or metric in PERCENT_COLUMNS or metric in CONTEXT_COLUMNS:
        return float(value) if pd.notna(value) else np.nan
    minutes = pd.to_numeric(row['Minutos jugados'], errors='coerce')
    return float(value) * 90 / float(minutes) if pd.notna(value) and pd.notna(minutes) and minutes > 0 else np.nan

def percentile_value(player, metric):
    peers = D[(D.Position == player.Position) & (D['Minutos jugados'] >= 180)]
    values = peers.apply(lambda r: metric_value(r, metric), axis=1).dropna()
    current = metric_value(player, metric)
    if not len(values) or not np.isfinite(current):
        return np.nan
    percentile = 100 * ((values < current).sum() + .5 * (values == current).sum()) / len(values)
    if metric in LOWER_IS_BETTER:
        percentile = 100 - percentile
    return round(float(percentile), 1)

def player_picker(side, title, default_index):
    clubs = sorted(D['Club'].dropna().unique().tolist())
    club = st.selectbox(COMPARE_I18N[lang]['club'] + ' · ' + title,
                        ['All clubs / Todos'] + clubs, key='compare_club_' + side)
    query = st.text_input(COMPARE_I18N[lang]['search'] + ' · ' + title,
                          key='compare_search_' + side)
    subset = D if club == 'All clubs / Todos' else D[D.Club == club]
    if query.strip():
        subset = subset[subset.Player.str.contains(query.strip(), case=False, na=False, regex=False)]
    if subset.empty:
        st.info(COMPARE_I18N[lang]['no_players'])
        return None
    opts = (subset.Player.astype(str) + ' · ' + subset.Club.astype(str)).tolist()
    picked = st.selectbox(COMPARE_I18N[lang]['choose'] + ' · ' + title,
                          range(len(subset)), index=min(default_index, len(subset)-1),
                          format_func=lambda i: opts[i], key='compare_player_' + side)
    return subset.iloc[picked]

def comparison_radar(a, b, metrics, title):
    fig = go.Figure()
    metrics = [m for m in metrics if m in D.columns]
    for player, color in [(a, '#f16b6b'), (b, '#65b9dc')]:
        scores = [percentile_value(player, m) for m in metrics]
        # Missing values must not be mistaken for zero performance.
        fig.add_trace(go.Scatterpolar(
            r=scores + scores[:1], theta=[metric_label(m) for m in metrics] + [metric_label(metrics[0])],
            fill='toself', name=str(player.Player), line=dict(color=color, width=2),
            fillcolor='rgba(241,107,107,0.15)' if color == '#f16b6b' else 'rgba(101,185,220,0.15)',
            hovertemplate='%{theta}: %{r:.1f} percentile<extra>%{fullData.name}</extra>'))
    fig.update_layout(title=dict(text=title, font=dict(size=18)),
                      template='plotly_dark', paper_bgcolor='#111e31', plot_bgcolor='#111e31',
                      polar=dict(bgcolor='#111e31', radialaxis=dict(range=[0,100], tickvals=[0,25,50,75,100],
                      gridcolor='#34435a'), angularaxis=dict(gridcolor='#34435a', tickfont=dict(size=10))),
                      legend=dict(orientation='h', y=-0.18), margin=dict(l=55,r=55,t=65,b=75),height=560)
    st.plotly_chart(fig, use_container_width=True)

